insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id from jsonb_to_recordset($bank$[{"id":"che-ek-253","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Half-life of a gaseous decay is 40 min at 0.80 bar initial pressure and 80 min at 0.40 bar. The order and $k$ (from the 0.80 bar run, treating concentration as proportional to $p$) are consistent with","options":["second order, because $t_{1/2}$ doubles when $p_0$ is halved","first order, because $t_{1/2}$ is independent of $p_0$","zero order, because $t_{1/2}$ halves when $p_0$ is halved","third order, because $t_{1/2} \\propto p_0^2$"],"answer_index":0,"explanation":"Second-order $t_{1/2} \\propto 1/[\\mathrm{A}]_0$. Halving the initial pressure doubles the half-life, which matches the data.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"integrated-half-life"},{"id":"che-ek-254","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A first-order hydrolysis has $k = 2.303 \\times 10^{-3}\\ \\mathrm{s^{-1}}$. The percentage of reactant still left after 1000 s is nearest","options":["10%","50%","1%","90%"],"answer_index":0,"explanation":"$\\log([\\mathrm{A}]_0/[\\mathrm{A}]) = kt/2.303 = 1.00$, so $[\\mathrm{A}]/[\\mathrm{A}]_0 = 0.10$ (10% remains).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"integrated-half-life"},{"id":"che-ek-255","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Activation energy $E_a$ of a reaction is the","options":["minimum extra energy that colliding molecules must possess if they are to react","heat released when products form","same quantity as $\\Delta H$ of the reaction","Faraday constant multiplied by $T$"],"answer_index":0,"explanation":"$E_a$ is the barrier height on the reaction profile. Only collisions that clear that barrier can form products.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"arrhenius-ea"},{"id":"che-ek-256","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For a typical activated reaction, raising the temperature causes the rate constant to","options":["increase","decrease toward zero","become equal to the Faraday constant","lose its units"],"answer_index":0,"explanation":"The Boltzmann factor $e^{-E_a/RT}$ grows as $T$ grows, so $k$ rises (often steeply).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"arrhenius-ea"},{"id":"che-ek-257","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A plot of $\\ln k$ versus $1/T$ for an Arrhenius reaction is a straight line whose slope equals","options":["$-E_a/R$","$E_a/R$","$-R/E_a$","$A$"],"answer_index":0,"explanation":"$\\ln k = \\ln A - E_a/RT$, so the slope versus $1/T$ is $-E_a/R$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"arrhenius-ea"},{"id":"che-ek-258","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"In $k = A e^{-E_a/RT}$ the pre-exponential factor $A$ is interpreted as","options":["a frequency (or collision) factor, the value $k$ would have if every collision were successful","the activation energy in joules","the gas constant","the equilibrium constant $K_c$"],"answer_index":0,"explanation":"$A$ absorbs the collision frequency and a steric factor. It has the same units as $k$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"arrhenius-ea"},{"id":"che-ek-259","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A catalyst speeds a reaction primarily by","options":["providing an alternative path with a lower activation energy","raising the temperature of the surroundings","increasing $\\Delta G^\\circ$ of the reaction","changing the stoichiometric coefficients"],"answer_index":0,"explanation":"A lower $E_a$ increases the fraction of successful collisions. $\\Delta H$ and the position of equilibrium stay the same.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"arrhenius-ea"},{"id":"che-ek-260","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Threshold energy in collision theory is","options":["the minimum relative kinetic energy that a collision must have to be potentially reactive","the average kinetic energy of the whole sample","equal to $RT$ at every temperature","the energy of the products minus $E_a$"],"answer_index":0,"explanation":"Molecules that meet with energy below the threshold simply bounce apart; those above it may react if oriented properly.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"arrhenius-ea"},{"id":"che-ek-261","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Activation energies of ordinary laboratory reactions are usually quoted in","options":["kJ mol$^{-1}$","volts","siemens","atomic mass units"],"answer_index":0,"explanation":"$E_a$ is a molar energy barrier, typically tens to a few hundred kJ mol$^{-1}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"arrhenius-ea"},{"id":"che-ek-262","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Between two reactions at the same $T$, the one with the larger $E_a$ is","options":["more sensitive to a change of temperature","always faster at every temperature","unaffected by heating","required to have a negative $A$ factor"],"answer_index":0,"explanation":"d ln $k$ / d$T$ = $E_a/RT^2$, so a higher barrier means a steeper rise of $k$ with $T$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"arrhenius-ea"},{"id":"che-ek-263","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The two-temperature form of the Arrhenius equation is","options":["$\\log(k_2/k_1) = (E_a/2.303R)(1/T_1 - 1/T_2)$","$\\log(k_2/k_1) = (E_a/R)(T_2 - T_1)$","$k_2/k_1 = E_a (T_2 - T_1)$","$\\log(k_2/k_1) = 2.303R / E_a$"],"answer_index":0,"explanation":"Subtracting $\\ln k = \\ln A - E_a/RT$ at two temperatures eliminates $A$ and gives that working equation.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"arrhenius-ea"},{"id":"che-ek-264","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"In the formal high-temperature limit of the Arrhenius expression, $k$ approaches","options":["the pre-exponential factor $A$","zero","the Faraday constant","$E_a$ itself"],"answer_index":0,"explanation":"As $T \\to \\infty$, $e^{-E_a/RT} \\to 1$, so $k \\to A$. Real molecules decompose before that limit is reached.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"arrhenius-ea"},{"id":"che-ek-265","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A reaction has $k = 2.0 \\times 10^{-3}\\ \\mathrm{s^{-1}}$ at 300 K and $8.0 \\times 10^{-3}\\ \\mathrm{s^{-1}}$ at 320 K. $E_a$ is nearest","options":["55 kJ mol$^{-1}$","8.3 kJ mol$^{-1}$","220 kJ mol$^{-1}$","2.0 kJ mol$^{-1}$"],"answer_index":0,"explanation":"$\\log 4 = 0.602 = (E_a/19.15)(1/300 - 1/320)$; $1/300 - 1/320 = 2.08 \\times 10^{-4}$, so $E_a \\approx 55\\ \\mathrm{kJ\\ mol^{-1}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"arrhenius-ea"},{"id":"che-ek-266","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"If $E_a = 57.4\\ \\mathrm{kJ\\ mol^{-1}}$, the factor by which $k$ grows when $T$ goes from 300 K to 310 K is nearest","options":["2","10","0.5","100"],"answer_index":0,"explanation":"$\\log(k_2/k_1) = (57400/19.15)(10/93000) \\approx 0.32$, so $k_2/k_1 \\approx 2$. This is the familiar “about double per 10 K” case.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"arrhenius-ea"},{"id":"che-ek-267","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Given $k = 1.0 \\times 10^{-4}\\ \\mathrm{s^{-1}}$ at 300 K and $E_a = 38.3\\ \\mathrm{kJ\\ mol^{-1}}$, $k$ at 310 K is nearest","options":["$1.6 \\times 10^{-4}\\ \\mathrm{s^{-1}}$","$1.0 \\times 10^{-5}\\ \\mathrm{s^{-1}}$","$3.8 \\times 10^{-2}\\ \\mathrm{s^{-1}}$","$1.0 \\times 10^{-4}\\ \\mathrm{s^{-1}}$"],"answer_index":0,"explanation":"$\\log(k_2/k_1) = (38300/19.15)(10/93000) \\approx 0.215$, so $k_2 \\approx 1.6 \\times 10^{-4}\\ \\mathrm{s^{-1}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"arrhenius-ea"},{"id":"che-ek-268","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"On an Arrhenius plot of $\\ln k$ versus $1/T$ the intercept (extrapolated to $1/T = 0$) equals","options":["$\\ln A$","$-E_a$","$A$","$E_a/R$"],"answer_index":0,"explanation":"$\\ln k = \\ln A - (E_a/R)(1/T)$. The intercept of that straight line is $\\ln A$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"arrhenius-ea"},{"id":"che-ek-269","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Two reactions have similar $A$ factors. At a given temperature the slower one is the one with","options":["the higher activation energy","the lower activation energy","the larger $n$ in the Nernst equation","the smaller Faraday equivalent"],"answer_index":0,"explanation":"$k = A e^{-E_a/RT}$ falls exponentially as $E_a$ rises, so the higher barrier is slower if $A$ is comparable.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"arrhenius-ea"},{"id":"che-ek-270","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"From $k(300\\ \\mathrm{K}) = 1.0 \\times 10^{-4}\\ \\mathrm{s^{-1}}$ and $k(310\\ \\mathrm{K}) = 2.0 \\times 10^{-4}\\ \\mathrm{s^{-1}}$, $k$ at 320 K is nearest","options":["$3.8 \\times 10^{-4}\\ \\mathrm{s^{-1}}$","$4.0 \\times 10^{-5}\\ \\mathrm{s^{-1}}$","$2.0 \\times 10^{-3}\\ \\mathrm{s^{-1}}$","$1.0 \\times 10^{-4}\\ \\mathrm{s^{-1}}$"],"answer_index":0,"explanation":"First $E_a$ from the 300/310 pair ($k$ doubles in 10 K, $E_a \\approx 53.6\\ \\mathrm{kJ\\ mol^{-1}}$), then $\\log(k_{320}/k_{300}) \\approx 0.58$, so $k_{320} \\approx 3.8 \\times 10^{-4}\\ \\mathrm{s^{-1}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"arrhenius-ea"},{"id":"che-ek-271","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Increasing the concentration of a reactant that appears in the rate law generally","options":["increases the reaction rate","decreases $k$ at constant $T$","stops the reaction completely","changes $\\Delta H$ of the reaction"],"answer_index":0,"explanation":"Rate $= k[\\mathrm{A}]^x\\ldots$ grows with [A] whenever the order $x$ is positive.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-factors"},{"id":"che-ek-272","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Heating a reaction mixture of thermally activated molecules typically","options":["speeds the reaction because more molecules clear the energy barrier","always shifts the equilibrium constant to 1","lowers $E_a$ of an uncatalysed path","has no kinetic effect below 100 °C"],"answer_index":0,"explanation":"Temperature enters $k$ through the Arrhenius factor. Equilibrium may also shift, but that is a separate thermodynamic effect.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-factors"}]$bank$::jsonb) as t(id text, chapter_id text, subject_id text, stem text, options jsonb, answer_index int, explanation text, images jsonb, source jsonb, difficulty text, concept_id text) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
insert into question_pyq_meta (question_id, appear_count, years, exams, verified) select question_id, appear_count, years, exams, verified from jsonb_to_recordset($meta$[{"question_id":"che-ek-253","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-254","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-255","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-256","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-257","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-258","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-259","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-260","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-261","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-262","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-263","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-264","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-265","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-266","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-267","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-268","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-269","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-270","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-271","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-272","appear_count":0,"years":[],"exams":[],"verified":false}]$meta$::jsonb) as t(question_id text, appear_count int, years int[], exams text[], verified boolean) on conflict (question_id) do 